import {esc} from '../config.mjs';
const date=value=>value?new Date(value).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}):'Ainda não registrada';
export function cleanupTotal(d){const e=d.eligible||{};return Number(e.unpaid||0)+Number(e.content||0)+Number(e.senderExpired||0)+(d.optionalEnabled?Number(e.reports||0)+Number(e.visits||0):0)}
export function dataCleanupMarkup(d,{reviewed=false}={}){
 const e=d.eligible||{},p=d.protected||{},total=cleanupTotal(d),jobs=new Map((d.jobs||[]).map(x=>[x.name,x]));
 const rows=[['Sem pagamento','20 minutos','unpaid','O comentário não pago é excluído. Pedidos com pagamento registrado ou em atenção ficam protegidos.'],['Conteúdo encerrado da Comunidade e LIVE','24 horas · conforme a conclusão','content','A LIVE ainda na fila não é apagada. Só sai conteúdo elegível; os registros financeiros ficam.'],['Registro privado do remetente','48 horas','senderExpired','Nome completo, telefone, IP e cópia privada seguem o vencimento do registro. Após pagamento, conta da primeira confirmação; sem pagamento, da criação.'],['Relatórios antigos','Mais de 30 dias','reports','Preserva os relatórios dos últimos 30 dias.'],['Aberturas de páginas antigas','Mais de 30 dias','visits','Remove apenas eventos antigos de abertura de página; não apaga o histórico de segurança.']];
 const last=d.lastResult||{},removed=['unpaidOrders','unpaidComments','contentRemoved','expiredSenders','reports','visits'].reduce((n,k)=>n+Number(last[k]||0),0);
 return `<section class="data-cleanup-screen"><div class="control-page-head"><div><h1>Dados e limpeza</h1><p>Veja o que fica protegido e apague somente o que já venceu.</p></div><button class="btn secondary" data-data-refresh>Atualizar</button></div><div class="data-protection-banner"><strong>IP, nome e telefone continuam protegidos pelo prazo de 48 horas.</strong><p>Retirar uma publicação do ar não elimina o registro privado antes do vencimento. Esta área não libera exclusão antecipada desses dados.</p><button class="btn secondary" data-data-senders>Consultar remetentes · 48h</button></div><div class="metrics">${[['Vencidos nesta limpeza',total],['Registros privados no prazo',p.senders||0],['Recibos financeiros preservados',p.payments||0],['Mensagens aguardando a LIVE',p.liveQueue||0],['Pagamentos em atenção',p.financialAttention||0]].map(([label,value])=>`<div class="metric"><b>${esc(value)}</b><span>${label}</span></div>`).join('')}</div><div class="paper"><h2>Limpar somente vencidos</h2><p>Confira a quantidade e limpe sem escolher registros um a um. O servidor revalida os prazos e as proteções na execução.</p><div class="actions"><button class="btn secondary" data-data-preview>Conferir vencidos</button><button class="btn danger" data-data-run ${reviewed&&total>0?'':'disabled'}>Limpar somente vencidos</button></div><p data-data-result role="status">${reviewed?esc(total)+' registros elegíveis nesta consulta.':'Confira os vencidos para liberar o botão de limpeza.'}</p><p class="hint">Até 1000 comentários por tipo e 1000 conteúdos por execução; se restarem vencidos, confira novamente. As rotinas automáticas também continuam processando a fila.</p></div><div class="data-deadlines">${rows.map(([title,deadline,key,detail])=>`<article class="paper"><div class="row wrap"><h2>${title}</h2><span class="badge">${deadline}</span></div><strong class="data-due-count">${esc(e[key]||0)} <small>vencidos</small></strong><p>${detail}</p>${['reports','visits'].includes(key)?`<small>${d.optionalEnabled?'Incluído na limpeza automática e neste botão.':'Automação opcional desativada; use a exclusão por área para uma limpeza manual.'}</small>`:''}</article>`).join('')}</div><form class="paper" data-data-preferences><h2>Deixar o app cuidar da limpeza</h2><p>As rotinas de 20 minutos, conteúdo elegível e dados privados de 48 horas continuam obrigatórias. A opção abaixo controla somente relatórios e acessos antigos.</p><label class="check"><input name="optional" type="checkbox" ${d.optionalEnabled?'checked':''}><span>Limpar automaticamente relatórios e aberturas de páginas com mais de 30 dias</span></label><button class="btn" type="submit">Salvar limpeza automática</button></form><div class="paper"><h2>Última limpeza central</h2><p>${esc(date(d.lastRun))}${d.lastRun?' · '+esc(removed)+' registros removidos ou conteúdos eliminados':''}</p><p class="hint">Horário de Brasília. As rotinas individuais também podem limpar vencidos entre duas execuções desta central.</p></div><div class="paper"><h2>Rotinas automáticas</h2>${[['hocco-expire-unpaid-comments','Comentários não pagos','A cada minuto'],['hocco-community-content-retention','Conteúdo encerrado','A cada 5 minutos'],['hocco-sender-evidence-48h','Dados privados vencidos','A cada minuto'],['hocco-message-data-cleanup','Limpeza central e opção de 30 dias','A cada hora']].map(([key,title,frequency])=>{const j=jobs.get(key),problem=!j?.enabled||j?.lastStatus==='failed';return `<div class="data-job"><strong>${title}</strong><span class="badge ${problem?'red':'success'}">${!j?'Rotina não encontrada':!j.enabled?'Pausada':j.lastStatus==='failed'?'Falha na última execução':'Ativa'}</span><small>${frequency} · última conclusão: ${esc(date(j?.lastFinished))}</small></div>`}).join('')}</div><div class="paper"><h2>Outras ações</h2><p>Para retirar uma mensagem antes do prazo, use a área dela. Para exclusão definitiva por categoria, confira os elegíveis na ferramenta abaixo.</p><div class="actions"><button class="btn secondary" data-control-route="community">Gerenciar Comunidade e LIVE</button><button class="btn secondary" data-control-route="trash">Abrir Lixeira</button><button class="btn secondary" data-control-route="finance">Conferir pagamentos</button><button class="btn secondary" data-data-advanced>Exclusão definitiva por área</button></div><p class="hint">Pagamentos, pendências de devolução ou entrega e registros privados ainda no prazo não são apagados pelo botão de vencidos. A exclusão definitiva exige confirmação, sem pedir justificativa.</p></div></section>`;
}
export function mountDataCleanup(host,call,{onSenders,onAdvanced,confirmAction=message=>confirm(message)}){
 let disposed=false,busy=false,generation=0;
 const error=document.createElement('p');error.className='error';error.setAttribute('role','alert');
 async function load(reviewed=false,result=''){
  const version=++generation;try{const d=await call('admin.data.status',{});if(disposed||version!==generation)return;host.innerHTML=dataCleanupMarkup(d,{reviewed});host.prepend(error);error.textContent='';
  host.querySelector('[data-data-refresh]').onclick=()=>load();host.querySelector('[data-data-preview]').onclick=()=>load(true);
  host.querySelector('[data-data-senders]').onclick=onSenders;host.querySelector('[data-data-advanced]').onclick=onAdvanced;
  if(result)host.querySelector('[data-data-result]').textContent=result;
  host.querySelector('[data-data-run]').onclick=async()=>{if(busy||!reviewed||!cleanupTotal(d))return;if(!confirmAction('Limpar apenas registros que já atingiram o prazo? A exclusão não pode ser desfeita. Dados privados no prazo, pagamentos e pendências serão preservados.'))return;busy=true;const b=host.querySelector('[data-data-run]');b.disabled=true;try{const r=await call('admin.data.cleanup',{confirmExpired:true}),n=['unpaidOrders','unpaidComments','contentRemoved','expiredSenders','reports','visits'].reduce((sum,k)=>sum+Number(r[k]||0),0);if(!disposed)await load(false,n+' registros vencidos removidos ou conteúdos eliminados.')}catch(e){if(!disposed){error.textContent=e.message;b.disabled=false}}finally{busy=false}};
  host.querySelector('[data-data-preferences]').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;const button=e.target.querySelector('button');button.disabled=true;try{await call('admin.data.preferences',{enabled:new FormData(e.target).has('optional')});if(!disposed)await load(false,'Preferência de limpeza automática salva.')}catch(e){if(!disposed){error.textContent=e.message;button.disabled=false}}finally{busy=false}};
  }catch(e){if(!disposed&&version===generation){host.innerHTML='<div class="empty"><h2>Não foi possível consultar a limpeza.</h2><p>'+esc(e.message)+'</p><button class="btn secondary" data-data-retry>Tentar novamente</button></div>';host.querySelector('[data-data-retry]').onclick=()=>load()}}
 }
 host.innerHTML='<div class="empty">Conferindo prazos e proteções…</div>';load();return()=>{disposed=true;generation++;host.replaceChildren()};
}
